import * as T from './assets/three.module.js';
import {surfaceTexture} from './textures.js?v=5';
import {buoyancyPose} from './surface.js?v=5';
import {BOATS} from './economy.js?v=5';
const TAU=Math.PI*2;
export function createWater(parent){let ocean=0,swell=1;const events=[];const impulses=Array.from({length:8},()=>new T.Vector4(0,0,-100,0));const uniforms={time:{value:0},ocean:{value:0},swell:{value:1},darkness:{value:0},impulses:{value:impulses}};
 const wave=`float height(vec2 p){float a=mix(.048,.22,ocean)*swell;float h=sin(p.x*.45+p.y*.68+time*.9)*a+sin(p.x*.71-p.y*.32+time*.7)*a*.55+sin(p.y*1.8+time*1.1)*.018+sin(p.x*1.3-p.y*.92+time*1.6)*a*.18;for(int i=0;i<8;i++){float age=time-impulses[i].z;float d=length(p-impulses[i].xy);if(age>0.&&age<8.)h+=sin(d*6.-age*8.)*exp(-pow(d-age*2.8,2.)*.7)*exp(-age*.65)*impulses[i].w;}return h;}`;
 const mat=new T.ShaderMaterial({uniforms,side:T.DoubleSide,vertexShader:`uniform float time;uniform float ocean;uniform float swell;uniform vec4 impulses[8];varying vec3 p;varying vec3 normalW;${wave}void main(){vec3 v=position;v.y=height(v.xz);float e=.08;normalW=normalize(vec3(height(v.xz-vec2(e,0.))-height(v.xz+vec2(e,0.)),2.*e,height(v.xz-vec2(0.,e))-height(v.xz+vec2(0.,e))));p=v;gl_Position=projectionMatrix*modelViewMatrix*vec4(v,1.);}`,fragmentShader:`uniform float time;uniform float ocean;uniform float darkness;varying vec3 p;varying vec3 normalW;void main(){vec3 n=normalize(normalW);vec3 view=normalize(cameraPosition-p);float f=pow(1.-max(0.,dot(view,n)),3.);vec3 deep=mix(vec3(.055,.19,.18),vec3(.035,.18,.25),ocean);vec3 shallow=mix(vec3(.15,.34,.28),vec3(.09,.43,.47),ocean);float bands=.5+.5*sin(p.x*.14+p.z*.18);vec3 color=mix(deep,shallow,bands*.45+.2);color=mix(color,vec3(.42,.57,.56),f*.65);vec3 light=normalize(vec3(-.4,.7,-.3));float sparkle=pow(max(0.,dot(reflect(-light,n),view)),95.);color+=sparkle*vec3(.85,.74,.51)*.75;float fine=sin(p.x*12.+p.z*8.+time)*sin(p.z*9.-time*.6);color+=max(0.,fine-.88)*.06;float foam=ocean*smoothstep(.27,.43,p.y)*.25;color+=foam*vec3(.55,.7,.67);color*=1.-darkness*.65;gl_FragColor=vec4(color,1.);}`});const geo=new T.PlaneGeometry(260,230,192,160);geo.rotateX(-Math.PI/2);geo.translate(0,0,-65);const mesh=new T.Mesh(geo,mat);parent.add(mesh);
 function height(x,z,t){const a=(ocean?.22:.048)*swell;let h=Math.sin(x*.45+z*.68+t*.9)*a+Math.sin(x*.71-z*.32+t*.7)*a*.55+Math.sin(z*1.8+t*1.1)*.018+Math.sin(x*1.3-z*.92+t*1.6)*a*.18;for(const e of events){const age=t-e.time,d=Math.hypot(x-e.x,z-e.z);if(age>0&&age<8)h+=Math.sin(d*6-age*8)*Math.exp(-Math.pow(d-age*2.8,2)*.7)*Math.exp(-age*.65)*e.power;}return h;}
 return {mesh,height,impulse(x,z,t,power=.22){events.push({x,z,time:t,power});if(events.length>8)events.shift();for(let i=0;i<8;i++){const e=events[i];impulses[i].set(e?.x||0,e?.z||0,e?.time??-100,e?.power||0);}},update(t,region,c){ocean=region>=3?1:0;swell=c.weather==='wind'?1.45:1;uniforms.time.value=t;uniforms.ocean.value=ocean;uniforms.swell.value=swell;uniforms.darkness.value=c.phase==='night'?.7:c.phase==='dusk'?.22:0;}};
}
export function createEnvironment(parent,state,water){const fresh=new T.Group(),salt=new T.Group(),common=new T.Group();parent.add(fresh,salt,common);salt.visible=false;const mat=(color,extra={})=>new T.MeshStandardMaterial({color,roughness:.85,...extra});const sphere=new T.SphereGeometry(1,16,12),box=new T.BoxGeometry(1,1,1),cyl=new T.CylinderGeometry(1,1,1,12);function mesh(g,m,p,s,par=fresh){const o=new T.Mesh(g,m);o.position.set(...p);o.scale.set(...s);par.add(o);return o;}
 function terrain(cx,cz,w,d,h,color,par=fresh){const g=new T.PlaneGeometry(w,d,48,72);g.rotateX(-Math.PI/2);const a=g.attributes.position;for(let i=0;i<a.count;i++){const x=a.getX(i),z=a.getZ(i),edge=Math.max(0,1-Math.pow(Math.abs(x)/(w*.5),2));const y=-.25+Math.pow(edge,.7)*(h+Math.sin(x*.25+z*.18)*h*.22+Math.sin(z*.47)*.2);a.setY(i,y);}g.computeVertexNormals();return mesh(g,mat(color),[cx,0,cz],[1,1,1],par);}
 terrain(-23,-7,27,68,3.4,'#55745b');terrain(27,-16,32,75,4.5,'#506f56');terrain(0,35,80,35,3,'#58715a');
 function ground(x,z){const left=x<0,cx=left?-23:27,cz=left?-7:-16,w=left?27:32,h=left?3.4:4.5,xx=x-cx,zz=z-cz,edge=Math.max(0,1-Math.pow(Math.abs(xx)/(w*.5),2));return -.25+Math.pow(edge,.7)*(h+Math.sin(xx*.25+zz*.18)*h*.22+Math.sin(zz*.47)*.2);}
 const treePositions=[];for(let i=0;i<44;i++){const side=i%2?-1:1;treePositions.push([side*(12+Math.random()*17),1.7+Math.random(),-35+Math.random()*55,3.5+Math.random()*5]);}
 const trunks=new T.InstancedMesh(cyl,mat('#6b5b46'),treePositions.length),canopy=new T.InstancedMesh(sphere,mat('#ffffff'),treePositions.length*9),matrix=new T.Object3D();fresh.add(trunks,canopy);let leaf=0;for(let i=0;i<treePositions.length;i++){const [x,y,z,h]=treePositions[i];matrix.position.set(x,y+h*.36,z);matrix.scale.set(.2,h*.72,.2);matrix.rotation.set(0,0,(Math.random()-.5)*.08);matrix.updateMatrix();trunks.setMatrixAt(i,matrix.matrix);for(let j=0;j<9;j++){const a=j*2.4,r=(j%3)*.6;matrix.position.set(x+Math.sin(a)*r,y+h*.72+(j%3)*.65,z+Math.cos(a)*r);matrix.scale.set(1.5+(j%2)*.4,1.3,1.5);matrix.rotation.set(.2*a,.3*a,.15*a);matrix.updateMatrix();canopy.setMatrixAt(leaf,matrix.matrix);canopy.setColorAt(leaf,new T.Color(['#41694e','#527b57','#365d48'][j%3]));leaf++;}}
 const grassGeo=new T.PlaneGeometry(.09,.8,1,3);grassGeo.translate(0,.4,0);const grass=new T.InstancedMesh(grassGeo,mat('#80916a',{side:T.DoubleSide}),1800);fresh.add(grass);for(let i=0;i<1800;i++){const side=i%2?-1:1;matrix.position.set(side*(11.3+Math.random()*15),1,-30+Math.random()*48);const xx=matrix.position.x-(side<0?-23:27),zz=matrix.position.z-(side<0?-7:-16),hh=side<0?3.4:4.5,ww=side<0?27:32,edge=Math.max(0,1-Math.pow(Math.abs(xx)/(ww*.5),2));matrix.position.y=-.25+Math.pow(edge,.7)*(hh+Math.sin(xx*.25+zz*.18)*hh*.22+Math.sin(zz*.47)*.2);matrix.scale.set(.7+Math.random(),.45+Math.random(),1);matrix.rotation.set(.05,Math.random()*TAU,(Math.random()-.5)*.4);matrix.updateMatrix();grass.setMatrixAt(i,matrix.matrix);}
 for(let i=0;i<38;i++){const side=i%2?-1:1;const stone=mesh(new T.DodecahedronGeometry(1,2),mat(['#849083','#75877d','#8b9181'][i%3]),[side*(7+Math.random()*9),.15,-28+Math.random()*41],[.4+Math.random()*.9,.3+Math.random()*.6,.4+Math.random()*.8]);stone.rotation.set(Math.random(),Math.random(),Math.random());}
 const glowMat=mat('#f7dcad',{emissive:'#e8b674',emissiveIntensity:.2});function house(x,z,scale=1,par=fresh){const h=new T.Group();h.position.set(x,par===fresh?ground(x,z):2,z);h.scale.setScalar(scale);par.add(h);mesh(box,mat('#b4ae93'),[0,1.5,0],[3.5,3,3],h);const roof=mesh(new T.ConeGeometry(1,1,4),mat('#5c6860'),[0,3.4,0],[3,1.5,2.7],h);roof.rotation.y=Math.PI/4;for(const xx of [-.9,.9])mesh(box,glowMat,[xx,1.6,1.515],[.65,.85,.04],h);mesh(box,mat('#657764'),[0,.9,1.52],[.6,1.8,.05],h);mesh(cyl,mat('#5d7065'),[1,3.7,-.6],[.22,1.5,.22],h);return h;}
 for(let i=0;i<6;i++)house(16+i*4.3,-29-(i%2)*5,.65+Math.random()*.3);
 const roadGeo=new T.PlaneGeometry(28,2.3,48,1);roadGeo.rotateX(-Math.PI/2);const roadVertices=roadGeo.attributes.position;for(let i=0;i<roadVertices.count;i++)roadVertices.setY(i,ground(roadVertices.getX(i)+25,roadVertices.getZ(i)-21)+.045);roadGeo.computeVertexNormals();const road=mesh(roadGeo,mat('#646c64'),[25,0,-21],[1,1,1]);const cars=[];for(let i=0;i<4;i++){const car=new T.Group();fresh.add(car);mesh(box,mat(['#a4b8b0','#bca187','#788c9d','#c8c1ad'][i]),[0,.5,0],[1.4,.55,.7],car);mesh(box,mat('#829c9e',{metalness:.35,roughness:.25}),[0,.9,0],[.75,.4,.64],car);for(const x of [-.45,.45])for(const z of [-.36,.36]){const wheel=mesh(cyl,mat('#35413e'),[x,.26,z],[.18,.09,.18],car);wheel.rotation.x=Math.PI/2;}cars.push(car);}
 const walkers=[];for(let i=0;i<12;i++){const person=new T.Group();fresh.add(person);mesh(sphere,mat(['#a58b78','#9cafa0','#8f9da9'][i%3]),[0,.55,0],[.15,.3,.13],person);mesh(sphere,mat('#c5a788'),[0,.97,0],[.12,.14,.12],person);for(const x of [-.07,.07])mesh(cyl,mat('#5d706a'),[x,.2,0],[.045,.45,.045],person);walkers.push(person);}
 // Coastal land, palms, and a small living waterfront.
 terrain(-42,-63,46,42,4,'#b5b28b',salt);terrain(44,-89,45,35,5,'#a1a985',salt);for(let i=0;i<11;i++){const x=-53+i*2.3,z=-64+(i%3)*3,h=4+(i%4);const palm=new T.Group();palm.position.set(x,2,z);salt.add(palm);mesh(cyl,mat('#9a8e69'),[0,h*.5,0],[.12,h,.12],palm);for(let j=0;j<7;j++){const shape=new T.Shape();shape.moveTo(0,0);shape.bezierCurveTo(.4,1.1,.3,2.4,0,3);shape.bezierCurveTo(-.3,2.3,-.4,.7,0,0);const frond=mesh(new T.ShapeGeometry(shape,15),mat('#68896a',{side:T.DoubleSide}),[0,h,0],[1,1,1],palm);frond.rotation.set(1.0,j*TAU/7,j*.1);}}
 for(let i=0;i<14;i++){const height=3+(i%5)*1.9;mesh(box,mat(i%2?'#b5bbaf':'#96aca9'),[-35+i*3.3,height*.5+1,-79-(i%3)*3],[2.2,height,2.6],salt);for(let j=0;j<Math.floor(height);j++)mesh(box,glowMat,[-35+i*3.3,j+1.7,-77.65-(i%3)*3],[1.5,.35,.035],salt);}
 function boat(size=1,style=0){const g=new T.Group(),pos=[],index=[];for(let i=0;i<=24;i++){const u=i/24,r=Math.pow(Math.sin(Math.PI*u),.55);for(let j=0;j<=12;j++){const a=j/12*Math.PI;pos.push((u-.5)*4,r*-Math.sin(a)*.7,r*Math.cos(a)*.86);}if(i<24)for(let j=0;j<12;j++){const a=i*13+j,b=a+13;index.push(a,b,a+1,b,b+1,a+1);}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(pos,3));geo.setIndex(index);geo.computeVertexNormals();mesh(geo,mat(BOATS[style]?.color||'#b4a787'),[0,0,0],[1,1,1],g);mesh(box,mat('#ab9c7b',{map:surfaceTexture('wood')}),[0,.025,0],[3.5,.12,1.48],g);for(const x of [-1,1])mesh(box,mat('#907f5e',{map:surfaceTexture('wood')}),[x,.2,0],[.45,.2,1.25],g);if(style>0){mesh(box,mat('#e0dccc'),[-1.3,.8,0],[1.1,1.3,1.05],g);mesh(box,mat('#8fadaf',{metalness:.3,roughness:.15}),[-1.3,1.1,.54],[.8,.55,.03],g);mesh(box,mat('#bdc9bd'),[-1.3,1.53,0],[1.45,.12,1.5],g);}if(style===2){mesh(cyl,mat('#bfcabc',{metalness:.6}),[-1.3,2.05,0],[.035,1.05,.035],g);mesh(box,mat('#bac9c5'),[-1.3,2.58,0],[.65,.08,.4],g);for(const side of [-1,1]){for(const x of [-1.5,-.6,.6,1.5])mesh(cyl,mat('#bdc9bb',{metalness:.6}),[x,.5,side*.74],[.025,.65,.025],g);mesh(box,mat('#bfcbbb',{metalness:.55}),[0,.82,side*.74],[3.3,.035,.035],g);}}g.scale.setScalar(size);return g;}
 const fleet=[];for(let i=0;i<5;i++){const b=boat(.5+i*.1,i%2);common.add(b);if(i%2===0){mesh(cyl,mat('#a8b4a6'),[0,1.5,0],[.035,3,.035],b);const sailGeo=new T.BufferGeometry().setFromPoints([new T.Vector3(.08,2.8,0),new T.Vector3(.08,.45,0),new T.Vector3(1.3,.45,0)]);sailGeo.setIndex([0,1,2]);sailGeo.computeVertexNormals();mesh(sailGeo,mat('#e3dec9',{side:T.DoubleSide}),[0,0,0],[1,1,1],b);}fleet.push(b);}
 let anchored=boat(1.55,state.boat),boatTier=state.boat;anchored.position.set(0,.35,8.7);salt.add(anchored);
 const titleShore=new T.Group();titleShore.visible=false;common.add(titleShore);terrain(17,23,18,22,1.4,'#b5ae8e',titleShore);for(let i=0;i<18;i++){const x=11+(i%6)*1.4,z=18+Math.floor(i/6)*2;mesh(new T.SphereGeometry(1,12,8),mat('#aaa78d'),[x,.5,z],[.2,.14,.3],titleShore);}
 const rainGeo=new T.BufferGeometry(),rainPos=[];for(let i=0;i<500;i++)rainPos.push((Math.random()-.5)*40,Math.random()*15,(Math.random()-.5)*45);rainGeo.setAttribute('position',new T.Float32BufferAttribute(rainPos,3));const rain=new T.Points(rainGeo,new T.PointsMaterial({color:'#b4cbd0',size:.035,transparent:true,opacity:.5}));common.add(rain);rain.visible=false;
 const sun=new T.Mesh(new T.SphereGeometry(2.5,24,16),new T.MeshBasicMaterial({color:'#ffe1a0'}));common.add(sun);const birds=[];for(let i=0;i<7;i++){const pts=[new T.Vector3(-.2,0,0),new T.Vector3(0,.09,0),new T.Vector3(.2,0,0)];const bird=new T.Line(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color:'#bcc9bb'}));common.add(bird);birds.push(bird);}
 return {update(dt,t,region,c){const ocean=region>=3;fresh.visible=!ocean;salt.visible=ocean;glowMat.emissiveIntensity=c.phase==='night'?1.4:c.phase==='dusk'?.8:.1;for(let i=0;i<cars.length;i++){const phase=(t*.55+i*7)%28;const carX=i%2?39-phase:11+phase,carZ=-21+(i%2?.45:-.45);cars[i].position.set(carX,ground(carX,carZ)+.08,carZ);cars[i].rotation.y=i%2?Math.PI:0;}for(let i=0;i<walkers.length;i++){const px=13+(t*.15+i*2.3)%27,pz=-19.3+(i%3)*.25;walkers[i].position.set(px,ground(px,pz)+.04,pz);walkers[i].rotation.z=Math.sin(t*3+i)*.015;walkers[i].children[2].rotation.x=Math.sin(t*3+i)*.4;walkers[i].children[3].rotation.x=-Math.sin(t*3+i)*.4;}for(let i=0;i<fleet.length;i++){const b=fleet[i];const bx=Math.sin(t*.015+i*1.7)*42,bz=-35-i*8;const pose=buoyancyPose(water.height,bx,bz,t,3,1.2);b.position.set(bx,pose.y,bz);b.rotation.y=Math.cos(t*.015+i*1.7)>0?0:Math.PI;b.rotation.x+=(pose.pitch-b.rotation.x)*(1-Math.exp(-dt*2.5));b.rotation.z+=(-pose.roll-b.rotation.z)*(1-Math.exp(-dt*2.5));b.visible=i<3||Math.sin(t*.02+i)>.3;}if(boatTier!==state.boat){salt.remove(anchored);anchored.traverse(o=>{if(o.isMesh){o.geometry.dispose();o.material.dispose();}});anchored=boat(1.55,state.boat);salt.add(anchored);boatTier=state.boat;}const hull=buoyancyPose(water.height,0,8.7,t,5.6,2.4),settle=1-Math.exp(-dt*2.6);anchored.position.x=0;anchored.position.z=8.7;anchored.position.y+=(.28+hull.y-anchored.position.y)*settle;anchored.rotation.x+=(hull.pitch-anchored.rotation.x)*settle;anchored.rotation.z+=(-hull.roll-anchored.rotation.z)*settle;rain.visible=c.weather==='rain';if(rain.visible){const a=rainGeo.attributes.position;for(let i=0;i<a.count;i++){let y=a.getY(i)-dt*9;if(y<0)y=15;a.setY(i,y);a.setX(i,a.getX(i)+dt*.4);}a.needsUpdate=true;}const angle=c.cycle/.64*Math.PI;sun.position.set(Math.cos(angle)*65,Math.sin(angle)*55+8,-95);sun.visible=c.phase!=='night';for(let i=0;i<birds.length;i++){birds[i].position.set(Math.sin(t*.04+i)*35,10+(i%3),-35-i*2);birds[i].scale.y=.8+Math.sin(t*4+i)*.4;}},setTitle(on){titleShore.visible=on;},get anchored(){return anchored;}};
}
